import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "MovieMatch — Swipe Movies Together",
  description: "Join a room with your couple, family, or friends, swipe on movie cards, and find the perfect match in real time.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex flex-col">{children}</body>
    </html>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import {
  Briefcase,
  Film,
  Heart,
  LogIn,
  Plus,
  Sparkles,
  Tv,
  Users,
  Users2,
} from "lucide-react";

const GROUP_TYPES = [
  {
    id: "couple",
    name: "Couple",
    icon: Heart,
    desc: "Romance, drama, comedies",
  },
  {
    id: "family",
    name: "Family",
    icon: Users,
    desc: "Animation, adventure, PG rating",
  },
  {
    id: "friends",
    name: "Friends",
    icon: Users2,
    desc: "Action, comedy, horror, sci-fi",
  },
  {
    id: "coworkers",
    name: "Coworkers",
    icon: Briefcase,
    desc: "Documentary, biopic, lighter fare",
  },
];

export default function Home() {
  const router = useRouter();
  const backendUrl =
    process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:8000";

  /* ── Intro state ──────────────────────────────────────────────────────── */
  const [showIntro, setShowIntro] = useState(false);
  const [introFading, setIntroFading] = useState(false);

  useEffect(() => {
    const played = sessionStorage.getItem("movieMatchIntroPlayed");
    if (!played) {
      setShowIntro(true);
    }
  }, []);

  const handleIntroEnd = () => {
    setIntroFading(true);
    setTimeout(() => {
      setShowIntro(false);
      sessionStorage.setItem("movieMatchIntroPlayed", "true");
    }, 800);
  };

  /* ── Action selection state ───────────────────────────────────────────── */
  const [activeAction, setActiveAction] = useState<"create" | "join" | "stream" | null>(null);

  const handleBack = () => {
    setActiveAction(null);
    setCreateError("");
    setJoinError("");
  };

  /* ── Create state ─────────────────────────────────────────────────────── */
  const [hostName, setHostName] = useState("");
  const [groupType, setGroupType] = useState("friends");
  const [isCreating, setIsCreating] = useState(false);
  const [createError, setCreateError] = useState("");

  /* ── Join state ───────────────────────────────────────────────────────── */
  const [guestName, setGuestName] = useState("");
  const [roomCode, setRoomCode] = useState("");
  const [isJoining, setIsJoining] = useState(false);
  const [joinError, setJoinError] = useState("");

  /* ── Handlers ─────────────────────────────────────────────────────────── */
  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!hostName.trim()) return setCreateError("Name is required");
    setCreateError("");
    setIsCreating(true);

    try {
      const res = await fetch(`${backendUrl}/api/rooms`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          host_name: hostName.trim(),
          group_type: groupType,
        }),
      });
      if (!res.ok) throw new Error((await res.json()).detail || "Failed to create room");

      const data = await res.json();
      // Store session identity in localStorage
      localStorage.setItem(
        `room_${data.room_code}_user`,
        JSON.stringify({ id: data.user_id, name: data.user_name, role: "host" })
      );
      router.push(`/room/${data.room_code}`);
    } catch (err: unknown) {
      setCreateError(err instanceof Error ? err.message : "Unknown error");
      setIsCreating(false);
    }
  };

  const handleCreateStreamRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!hostName.trim()) return setCreateError("Name is required");
    setCreateError("");
    setIsCreating(true);

    try {
      const res = await fetch(`${backendUrl}/api/rooms`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          host_name: hostName.trim(),
          group_type: "stream",
        }),
      });
      if (!res.ok) throw new Error((await res.json()).detail || "Failed to create stream room");

      const data = await res.json();
      // Store session identity in localStorage
      localStorage.setItem(
        `room_${data.room_code}_user`,
        JSON.stringify({ id: data.user_id, name: data.user_name, role: "host" })
      );
      router.push(`/room/${data.room_code}`);
    } catch (err: unknown) {
      setCreateError(err instanceof Error ? err.message : "Unknown error");
      setIsCreating(false);
    }
  };

  const handleJoin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!guestName.trim()) return setJoinError("Name is required");
    if (roomCode.length < 4) return setJoinError("Enter a valid room code");
    setJoinError("");
    setIsJoining(true);

    const code = roomCode.trim().toUpperCase();
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/join`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: guestName.trim() }),
      });
      if (!res.ok) throw new Error((await res.json()).detail || "Could not join room");

      const data = await res.json();
      localStorage.setItem(
        `room_${data.room_code}_user`,
        JSON.stringify({ id: data.user_id, name: data.user_name, role: "guest" })
      );
      router.push(`/room/${data.room_code}`);
    } catch (err: unknown) {
      setJoinError(err instanceof Error ? err.message : "Unknown error");
      setIsJoining(false);
    }
  };

  /* ── Render ───────────────────────────────────────────────────────────── */
  return (
    <div className="flex-1 flex flex-col items-center justify-center p-4 min-h-screen relative overflow-hidden">
      {/* Netflix-style opening intro video */}
      {showIntro && (
        <div
          className={`fixed inset-0 z-50 flex items-center justify-center bg-black transition-opacity duration-700 ease-out ${
            introFading ? "opacity-0 pointer-events-none" : "opacity-100"
          }`}
        >
          <video
            src="/loaders/landingloader.mp4"
            autoPlay
            muted
            playsInline
            onEnded={handleIntroEnd}
            className="w-full h-full object-cover md:object-contain max-w-5xl max-h-screen"
          />
          <button
            onClick={handleIntroEnd}
            className="absolute bottom-8 right-8 z-50 px-5 py-2.5 bg-zinc-900/80 hover:bg-zinc-800 text-white rounded-full text-xs font-bold uppercase tracking-wider border border-zinc-700/50 backdrop-blur transition-all active:scale-95 cursor-pointer shadow-lg"
          >
            Skip Intro
          </button>
        </div>
      )}

      {/* Background glows */}
      <div className="absolute top-[10%] left-[15%] w-[40rem] h-[40rem] bg-indigo-600/10 rounded-full blur-[140px] pointer-events-none -z-10" />
      <div className="absolute bottom-[10%] right-[15%] w-[40rem] h-[40rem] bg-pink-600/10 rounded-full blur-[140px] pointer-events-none -z-10" />

      {/* Hero */}
      <div className="text-center mb-10 max-w-lg mx-auto">
        {/* Brand Logo with Premium Glow */}
        <div className="relative group mb-6 select-none block mx-auto max-w-[280px] w-full">
          <div className="absolute inset-0 bg-gradient-to-tr from-indigo-500/15 to-pink-500/15 rounded-full blur-xl group-hover:scale-110 transition-transform duration-700 -z-10" />
          <img
            src="/loaders/logo.png"
            alt="MovieMatch Logo"
            className="w-48 md:w-56 h-auto mx-auto object-contain transition-all duration-500 group-hover:scale-105"
            style={{
              filter: "drop-shadow(0 0 20px rgba(99, 102, 241, 0.45)) drop-shadow(0 0 8px rgba(219, 39, 119, 0.25))"
            }}
          />
        </div>

        <div className="flex items-center justify-center gap-2 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 px-3 py-1.5 rounded-full text-xs font-semibold uppercase tracking-wider mb-5 animate-pulse-slow w-fit mx-auto">
          <Sparkles className="w-3.5 h-3.5" />
          Real-time Group Swiping
        </div>
        <h1 className="text-5xl md:text-6xl font-black tracking-tight text-white mb-3">
          Movie
          <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400">
            Match
          </span>
        </h1>
        <p className="text-zinc-400 text-sm md:text-base leading-relaxed">
          Create a room, invite your people, swipe movies independently, and
          discover your perfect match in real time.
        </p>
      </div>

      {/* Cards */}
      {activeAction === null ? (
        <div className="grid md:grid-cols-3 gap-6 w-full max-w-4xl animate-fade-in">
          {/* Card to Create Room */}
          <button
            onClick={() => setActiveAction("create")}
            className="group glass glass-glow rounded-3xl p-6 text-left transition-all duration-300 hover:scale-[1.02] cursor-pointer flex flex-col justify-between min-h-[220px] relative overflow-hidden"
          >
            <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/0 to-indigo-500/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
            <div className="space-y-4 relative z-10">
              <div className="p-3 bg-indigo-500/10 text-indigo-400 rounded-2xl border border-indigo-500/20 w-fit group-hover:bg-indigo-500 group-hover:text-white transition-all duration-300">
                <Plus className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-xl font-black text-white group-hover:text-indigo-400 transition-colors">
                  Create Room
                </h2>
                <p className="text-xs text-zinc-400 leading-relaxed mt-2">
                  Start a new session, choose group types, select preferences, and swipe movies together.
                </p>
              </div>
            </div>
            <div className="text-xs font-bold text-indigo-400 mt-6 flex items-center gap-1 group-hover:translate-x-1 transition-transform">
              Get Started &rarr;
            </div>
          </button>

          {/* Card to Create Direct Watch Party */}
          <button
            onClick={() => setActiveAction("stream")}
            className="group glass glass-glow rounded-3xl p-6 text-left transition-all duration-300 hover:scale-[1.02] cursor-pointer flex flex-col justify-between min-h-[220px] relative overflow-hidden"
          >
            <div className="absolute inset-0 bg-gradient-to-br from-purple-500/0 to-purple-500/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
            <div className="space-y-4 relative z-10">
              <div className="p-3 bg-purple-500/10 text-purple-400 rounded-2xl border border-purple-500/20 w-fit group-hover:bg-purple-500 group-hover:text-white transition-all duration-300">
                <Tv className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-xl font-black text-white group-hover:text-purple-400 transition-colors">
                  Direct Stream
                </h2>
                <p className="text-xs text-zinc-400 leading-relaxed mt-2">
                  Bypass movie swiping entirely. Create a room to instantly upload and stream movies with synced playback.
                </p>
              </div>
            </div>
            <div className="text-xs font-bold text-purple-400 mt-6 flex items-center gap-1 group-hover:translate-x-1 transition-transform">
              Watch Party &rarr;
            </div>
          </button>

          {/* Card to Join Room */}
          <button
            onClick={() => setActiveAction("join")}
            className="group glass glass-glow rounded-3xl p-6 text-left transition-all duration-300 hover:scale-[1.02] cursor-pointer flex flex-col justify-between min-h-[220px] relative overflow-hidden"
          >
            <div className="absolute inset-0 bg-gradient-to-br from-pink-500/0 to-pink-500/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
            <div className="space-y-4 relative z-10">
              <div className="p-3 bg-pink-500/10 text-pink-400 rounded-2xl border border-pink-500/20 w-fit group-hover:bg-pink-500 group-hover:text-white transition-all duration-300">
                <LogIn className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-xl font-black text-white group-hover:text-pink-400 transition-colors">
                  Join Room
                </h2>
                <p className="text-xs text-zinc-400 leading-relaxed mt-2">
                  Have a room code? Enter your friend's code to enter their lobby and select your vibe.
                </p>
              </div>
            </div>
            <div className="text-xs font-bold text-pink-400 mt-6 flex items-center gap-1 group-hover:translate-x-1 transition-transform">
              Join Session &rarr;
            </div>
          </button>
        </div>
      ) : activeAction === "create" ? (
        /* ── Create Form Card ── */
        <div className="glass glass-glow rounded-3xl p-8 w-full max-w-lg relative animate-fade-in">
          <button
            onClick={handleBack}
            className="absolute top-4 left-4 flex items-center gap-1 text-xs text-zinc-500 hover:text-white transition-colors cursor-pointer select-none font-bold"
          >
            &larr; Back
          </button>

          <form onSubmit={handleCreate} className="space-y-5 pt-4">
            <div className="flex items-center gap-3 mb-1">
              <div className="p-2.5 bg-indigo-500/10 text-indigo-400 rounded-xl border border-indigo-500/20">
                <Plus className="w-5 h-5" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Create a Session</h2>
                <p className="text-xs text-zinc-500">Start a new group matching deck</p>
              </div>
            </div>

            <div className="space-y-1.5">
              <label htmlFor="hostName" className="text-xs font-semibold text-zinc-300">
                Your Name
              </label>
              <input
                id="hostName"
                type="text"
                value={hostName}
                onChange={(e) => setHostName(e.target.value)}
                placeholder="e.g. Atul"
                className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-indigo-500/60 text-white rounded-xl px-4 py-3 text-sm outline-none transition-colors placeholder:text-zinc-600"
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-semibold text-zinc-300">
                Group Type
              </label>
              <div className="grid grid-cols-2 gap-2.5">
                {GROUP_TYPES.map((t) => {
                  const Icon = t.icon;
                  const sel = groupType === t.id;
                  return (
                    <button
                      key={t.id}
                      type="button"
                      onClick={() => setGroupType(t.id)}
                      className={`flex flex-col items-start text-left p-3 rounded-xl border transition-all cursor-pointer ${
                        sel
                          ? "border-indigo-500 bg-indigo-500/10 shadow-[0_0_18px_rgba(99,102,241,0.2)]"
                          : "border-zinc-800 bg-zinc-900/20 hover:border-zinc-700"
                      }`}
                    >
                      <Icon
                        className={`w-4 h-4 mb-2 ${sel ? "text-indigo-400" : "text-zinc-500"}`}
                      />
                      <span className="text-xs font-bold text-zinc-200 block mb-0.5">
                        {t.name}
                      </span>
                      <span className="text-[10px] text-zinc-500 leading-tight">
                        {t.desc}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>

            {createError && (
              <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/20 px-3 py-2 rounded-lg">
                {createError}
              </p>
            )}

            <button
              type="submit"
              disabled={isCreating}
              className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 disabled:opacity-50 text-white rounded-xl py-3 font-semibold text-sm shadow-[0_4px_25px_rgba(99,102,241,0.3)] transition-all active:scale-[0.98] cursor-pointer"
            >
              {isCreating ? "Creating…" : "Create Room"}
            </button>
          </form>
        </div>
      ) : activeAction === "stream" ? (
        /* ── Create Stream Room Form Card ── */
        <div className="glass glass-glow rounded-3xl p-8 w-full max-w-md relative animate-fade-in">
          <button
            onClick={handleBack}
            className="absolute top-4 left-4 flex items-center gap-1 text-xs text-zinc-500 hover:text-white transition-colors cursor-pointer select-none font-bold"
          >
            &larr; Back
          </button>

          <form onSubmit={handleCreateStreamRoom} className="space-y-5 pt-4">
            <div className="flex items-center gap-3 mb-1">
              <div className="p-2.5 bg-purple-500/10 text-purple-400 rounded-xl border border-purple-500/20">
                <Tv className="w-5 h-5" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Direct Stream Room</h2>
                <p className="text-xs text-zinc-500">Host a watch party directly</p>
              </div>
            </div>

            <div className="space-y-1.5">
              <label htmlFor="streamHostName" className="text-xs font-semibold text-zinc-300">
                Your Name
              </label>
              <input
                id="streamHostName"
                type="text"
                value={hostName}
                onChange={(e) => setHostName(e.target.value)}
                placeholder="e.g. Atul"
                className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-purple-500/60 text-white rounded-xl px-4 py-3 text-sm outline-none transition-colors placeholder:text-zinc-600"
              />
            </div>

            {createError && (
              <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/20 px-3 py-2 rounded-lg">
                {createError}
              </p>
            )}

            <button
              type="submit"
              disabled={isCreating}
              className="w-full bg-gradient-to-r from-purple-500 to-indigo-600 hover:from-purple-600 hover:to-indigo-700 disabled:opacity-50 text-white rounded-xl py-3 font-semibold text-sm shadow-[0_4px_25px_rgba(168,85,247,0.3)] transition-all active:scale-[0.98] cursor-pointer"
            >
              {isCreating ? "Creating Stream Room…" : "Start Watch Party"}
            </button>
          </form>
        </div>
      ) : (
        /* ── Join Form Card ── */
        <div className="glass glass-glow rounded-3xl p-8 w-full max-w-md relative animate-fade-in">
          <button
            onClick={handleBack}
            className="absolute top-4 left-4 flex items-center gap-1 text-xs text-zinc-500 hover:text-white transition-colors cursor-pointer select-none font-bold"
          >
            &larr; Back
          </button>

          <form onSubmit={handleJoin} className="space-y-5 pt-4">
            <div className="flex items-center gap-3 mb-1">
              <div className="p-2.5 bg-pink-500/10 text-pink-400 rounded-xl border border-pink-500/20">
                <LogIn className="w-5 h-5" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Join a Session</h2>
                <p className="text-xs text-zinc-500">Enter a code from a friend</p>
              </div>
            </div>

            <div className="space-y-1.5">
              <label htmlFor="guestName" className="text-xs font-semibold text-zinc-300">
                Your Name
              </label>
              <input
                id="guestName"
                type="text"
                value={guestName}
                onChange={(e) => setGuestName(e.target.value)}
                placeholder="e.g. Priya"
                className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-pink-500/60 text-white rounded-xl px-4 py-3 text-sm outline-none transition-colors placeholder:text-zinc-600"
              />
            </div>

            <div className="space-y-1.5">
              <label htmlFor="roomCode" className="text-xs font-semibold text-zinc-300">
                Room Code
              </label>
              <input
                id="roomCode"
                type="text"
                value={roomCode}
                onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
                placeholder="LION42"
                maxLength={8}
                className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-pink-500/60 text-white rounded-xl px-4 py-3 text-sm outline-none tracking-[0.3em] text-center font-bold transition-colors placeholder:tracking-normal placeholder:font-normal placeholder:text-zinc-600"
              />
            </div>

            {joinError && (
              <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/20 px-3 py-2 rounded-lg">
                {joinError}
              </p>
            )}

            <button
              type="submit"
              disabled={isJoining}
              className="w-full bg-gradient-to-r from-pink-500 to-rose-600 hover:from-pink-600 hover:to-rose-700 disabled:opacity-50 text-white rounded-xl py-3 font-semibold text-sm shadow-[0_4px_25px_rgba(219,39,119,0.3)] transition-all active:scale-[0.98] cursor-pointer"
            >
              {isJoining ? "Joining…" : "Join Room"}
            </button>
          </form>
        </div>
      )}

      {/* Footer hint */}
      <p className="mt-10 text-xs text-zinc-600 flex items-center gap-1.5">
        <Film className="w-3.5 h-3.5" />
        No account needed — just a name and a vibe.
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import {
  AlertCircle,
  ArrowLeft,
  Check,
  Copy,
  Film,
  Play,
  RefreshCw,
  Sparkles,
  Star,
  Users,
} from "lucide-react";
import Confetti from "@/components/Confetti";
import SwipeDeck from "@/components/SwipeDeck";
import VideoLoader from "@/components/VideoLoader";
import WatchRoomView from "@/components/WatchRoomView";

/* ── Types ────────────────────────────────────────────────────────────────── */

interface RoomUser {
  id: string;
  name: string;
  role: "host" | "guest";
}

interface Member {
  id: string;
  name: string;
  genres?: string[];
  notified?: boolean;
}

interface MovieCard {
  tmdb_id: string;
  position: number;
  title: string;
  overview: string | null;
  poster_path: string | null;
  genres: string | null;
  rating: number | null;
  runtime: number | null;
  streaming_info: string | null;
}

interface MatchMovie {
  tmdb_id: string;
  title: string;
  overview: string | null;
  poster_path: string | null;
  genres: string | null;
  rating: number | null;
  runtime: number | null;
  streaming_info: string | null;
  yes_count: number;
  is_unanimous: boolean;
}

interface MatchResult {
  total_members: number;
  matches: MatchMovie[];
}

type RoomState = "waiting" | "swiping" | "revealed" | "streaming";

type ProgressMap = Record<
  string,
  { name: string; voted: number; total: number }
>;

const AVAILABLE_GENRES = [
  "Action",
  "Comedy",
  "Romance",
  "Drama",
  "Sci-Fi",
  "Horror",
  "Thriller",
  "Documentary",
  "Animation",
];

/* ── Component ────────────────────────────────────────────────────────────── */

export default function RoomPage() {
  const params = useParams();
  const router = useRouter();
  const code = (params.code as string).toUpperCase();
  const backendUrl =
    process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:8000";

  /* user identity */
  const [user, setUser] = useState<RoomUser | null>(null);
  const [loadingUser, setLoadingUser] = useState(true);

  /* direct-join form (when arriving via invite link) */
  const [directName, setDirectName] = useState("");
  const [directError, setDirectError] = useState("");
  const [joiningDirect, setJoiningDirect] = useState(false);

  /* room state */
  const [roomState, setRoomState] = useState<RoomState>("waiting");
  const [groupType, setGroupType] = useState("");
  const [members, setMembers] = useState<Member[]>([]);
  const [movies, setMovies] = useState<MovieCard[]>([]);
  const [progress, setProgress] = useState<ProgressMap>({});
  const [matches, setMatches] = useState<MatchResult | null>(null);
  const [selectedGenres, setSelectedGenres] = useState<string[]>([]);

  /* ui */
  const [copiedCode, setCopiedCode] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  /* movie streaming upload state */
  const [uploadingMovie, setUploadingMovie] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [customTitle, setCustomTitle] = useState("");
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [uploadError, setUploadError] = useState("");

  const moviesLoadedRef = useRef(false);
  const matchesLoadedRef = useRef(false);
  const genresInitializedRef = useRef(false);
  const socketRef = useRef<WebSocket | null>(null);

  /* ── 2. Load user from localStorage ──────────────────────────────────── */
  useEffect(() => {
    const saved = localStorage.getItem(`room_${code}_user`);
    if (saved) {
      try {
        setUser(JSON.parse(saved));
      } catch {
        /* ignore corrupt data */
      }
    }
    setLoadingUser(false);
  }, [code]);

  /* ── 3. Fetch room details ────────────────────────────────────────────── */
  const fetchRoom = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}`);
      if (!res.ok) throw new Error("Room not found");
      const data = await res.json();
      setGroupType(data.group_type);
      setRoomState(data.state as RoomState);
      setMembers(data.members);
      setErrorMsg(""); // Clear errors on success

      // Initialize progress mapping from database values
      if (data.state === "swiping" || data.state === "revealed") {
        const initProgress: ProgressMap = {};
        data.members.forEach((m: any) => {
          if (m.voted_count !== undefined && m.voted_count !== null) {
            initProgress[m.id] = {
              name: m.name,
              voted: m.voted_count,
              total: 20,
            };
          }
        });
        setProgress(initProgress);
      }

      // Initialize selected genres for this user from room details response (ONLY ONCE)
      if (user && !genresInitializedRef.current) {
        const me = data.members.find((m: any) => m.id === user.id);
        if (me && me.genres) {
          setSelectedGenres(me.genres);
          genresInitializedRef.current = true;
        }
      }

      if (data.state === "swiping" && !moviesLoadedRef.current) {
        fetchDeck();
      }
      if (data.state === "revealed" && !matchesLoadedRef.current) {
        fetchMatches();
      }
    } catch (err: unknown) {
      setErrorMsg(err instanceof Error ? err.message : "Failed to load room");
    }
  };

  const fetchDeck = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/recs`);
      if (res.ok) {
        setMovies(await res.json());
        moviesLoadedRef.current = true;
      }
    } catch (err) {
      console.error("Failed to fetch deck:", err);
    }
  };

  const fetchMatches = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/matches`);
      if (res.ok) {
        setMatches(await res.json());
        matchesLoadedRef.current = true;
      }
    } catch (err) {
      console.error("Failed to fetch matches:", err);
    }
  };

  /* ── 4. Short Polling & WebSocket Real-time Sync ──────────────────────── */
  useEffect(() => {
    if (loadingUser || !user) return;

    // Initial fetch
    fetchRoom();

    // Poll every 2 seconds (as backup/sync fallback)
    const interval = setInterval(() => {
      fetchRoom();
    }, 2000);

    // Connect to WebSocket
    let reconnectTimeout: NodeJS.Timeout;
    let reconnectDelay = 3000;

    const connect = () => {
      const wsProto = window.location.protocol === "https:" ? "wss:" : "ws:";

      // Resolve host dynamically to avoid Windows localhost IPv6 ([::1]) vs IPv4 (127.0.0.1) resolution issues
      let backendHost = backendUrl.replace(/^https?:\/\//, "");
      if (backendHost.startsWith("localhost:")) {
        const port = backendHost.split(":")[1] || "8000";
        if (window.location.hostname !== "localhost" && window.location.hostname !== "") {
          backendHost = `${window.location.hostname}:${port}`;
        } else {
          backendHost = `127.0.0.1:${port}`;
        }
      }

      const wsUrl = `${wsProto}//${backendHost}/ws/${code}/${user.id}`;

      console.log("Connecting to WebSocket:", wsUrl);
      const ws = new WebSocket(wsUrl);
      socketRef.current = ws;

      ws.onopen = () => {
        console.log("WebSocket connection established");
        reconnectDelay = 3000; // Reset delay on success
      };

      ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.event === "state_changed") {
            setRoomState(data.state as RoomState);
            if (data.state === "swiping" && !moviesLoadedRef.current) {
              fetchDeck();
            }
            if (data.state === "revealed") {
              if (data.matches) {
                setMatches(data.matches);
                matchesLoadedRef.current = true;
              } else {
                fetchMatches();
              }
            }
          } else if (data.event === "participant_joined" || data.event === "participant_left") {
            if (data.participants) {
              const newMembers = data.participants.map((p: any) => ({
                id: p.id,
                name: p.name,
                genres: p.genres,
                notified: p.notified
              }));
              setMembers(newMembers);
            }
          } else if (data.event === "vote_progress") {
            setProgress((prev) => ({
              ...prev,
              [data.user_id]: {
                name: data.user_name,
                voted: data.voted_count,
                total: data.total_count,
              },
            }));
          }
        } catch (err) {
          console.error("Error processing WebSocket message:", err);
        }
      };

      ws.onclose = (event) => {
        console.log(`WebSocket connection closed (code: ${event.code}). Reconnecting in ${reconnectDelay / 1000}s...`);
        reconnectTimeout = setTimeout(() => {
          connect();
        }, reconnectDelay);
        reconnectDelay = Math.min(reconnectDelay * 1.5, 30000); // Exponential backoff up to 30s
      };

      ws.onerror = (err) => {
        console.error("WebSocket error:", err);
      };
    };

    connect();

    return () => {
      clearInterval(interval);
      if (socketRef.current) {
        socketRef.current.onclose = null;
        socketRef.current.close();
      }
      clearTimeout(reconnectTimeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadingUser, user]);

  /* ── 4. Actions ───────────────────────────────────────────────────────── */
  const startSession = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/start`, {
        method: "POST",
      });
      if (!res.ok) {
        throw new Error((await res.json()).detail || "Could not start session");
      }
    } catch (err: unknown) {
      setErrorMsg(err instanceof Error ? err.message : "Network error - failed to start session");
    }
  };

  const castVote = async (tmdbId: string, choice: boolean) => {
    if (!user) return;
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/vote`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, tmdb_id: tmdbId, choice }),
      });
      if (!res.ok) {
        throw new Error((await res.json()).detail || "Failed to record vote");
      }
    } catch (err: unknown) {
      console.error("Failed to cast vote:", err);
      setErrorMsg(err instanceof Error ? err.message : "Network error - failed to save vote");
    }
  };

  const forceReveal = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/reveal`, {
        method: "POST",
      });
      if (!res.ok) {
        throw new Error((await res.json()).detail || "Could not reveal matches");
      }
      const data = await res.json();
      setMatches(data);
      setRoomState("revealed");
    } catch (err: unknown) {
      setErrorMsg(err instanceof Error ? err.message : "Failed to force reveal matches");
    }
  };

  const toggleGenre = async (genre: string) => {
    if (!user) return;
    const updated = selectedGenres.includes(genre)
      ? selectedGenres.filter((g) => g !== genre)
      : [...selectedGenres, genre];

    setSelectedGenres(updated);

    try {
      const res = await fetch(`${backendUrl}/api/users/${user.id}/genres`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ genres: updated }),
      });
      if (!res.ok) {
        console.error("Failed to save genres to backend");
      }
    } catch (err) {
      console.error("Failed to save genres:", err);
    }
  };

  const joinDirect = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!directName.trim()) return setDirectError("Name is required");
    setDirectError("");
    setJoiningDirect(true);
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/join`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: directName.trim() }),
      });
      if (!res.ok)
        throw new Error((await res.json()).detail || "Could not join room");
      const data = await res.json();
      const newUser: RoomUser = {
        id: data.user_id,
        name: data.user_name,
        role: "guest",
      };
      localStorage.setItem(`room_${code}_user`, JSON.stringify(newUser));
      setUser(newUser);
    } catch (err: unknown) {
      setDirectError(err instanceof Error ? err.message : "Failed to join");
      setJoiningDirect(false);
    }
  };

  const copyCode = () => {
    navigator.clipboard.writeText(code);
    setCopiedCode(true);
    setTimeout(() => setCopiedCode(false), 2500);
  };

  const copyLink = () => {
    navigator.clipboard.writeText(`${window.location.origin}/room/${code}`);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2500);
  };

  const notifyPlayer = async (userId: string) => {
    try {
      const res = await fetch(`${backendUrl}/api/users/${userId}/notify`, {
        method: "POST",
      });
      if (!res.ok) {
        console.error("Failed to notify player");
      } else {
        fetchRoom();
      }
    } catch (err) {
      console.error("Failed to notify player:", err);
    }
  };

  const handleUploadMovie = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFile || !user) return;

    const titleToUse = customTitle.trim() || (matches?.matches[0]?.title) || "Group Watch Party";

    setUploadingMovie(true);
    setUploadProgress(0);
    setUploadError("");

    let supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

    if (supabaseUrl && anonKey) {
      // Normalize URL (strip trailing slashes and /rest/v1 path suffix)
      supabaseUrl = supabaseUrl.replace(/\/+$/, "").replace(/\/rest\/v1$/, "");

      // Direct upload to Supabase Storage (Bypasses Vercel payload limit)
      const filename = `${code}_${Date.now()}_${selectedFile.name.replace(/[^a-zA-Z0-9.]/g, "_")}`;
      const uploadUrl = `${supabaseUrl}/storage/v1/object/MovieMatch/${filename}`;

      try {
        const xhr = new XMLHttpRequest();
        xhr.open("POST", uploadUrl, true);
        xhr.setRequestHeader("Authorization", `Bearer ${anonKey}`);
        xhr.setRequestHeader("apikey", anonKey);

        xhr.upload.onprogress = (event) => {
          if (event.lengthComputable) {
            const percent = Math.round((event.loaded / event.total) * 100);
            setUploadProgress(percent);
          }
        };

        xhr.onload = async () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            const publicUrl = `${supabaseUrl}/storage/v1/object/public/MovieMatch/${filename}`;

            try {
              const res = await fetch(`${backendUrl}/api/rooms/${code}/stream_url`, {
                method: "POST",
                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                body: new URLSearchParams({
                  title: titleToUse,
                  host_id: user.id,
                  stream_url: publicUrl
                })
              });
              if (res.ok) {
                console.log("Direct upload & registration completed successfully!");
                setSelectedFile(null);
                setCustomTitle("");
                setRoomState("streaming");
              } else {
                setUploadError("Failed to register stream URL on backend.");
              }
            } catch (err: any) {
              setUploadError("Network error registering stream URL on backend.");
            }
          } else {
            setUploadError("Failed to upload video to Supabase Storage.");
          }
          setUploadingMovie(false);
        };

        xhr.onerror = () => {
          setUploadError("Network error occurred during direct upload.");
          setUploadingMovie(false);
        };

        xhr.send(selectedFile);
      } catch (err: any) {
        setUploadError(err.message || "Failed to initiate direct upload.");
        setUploadingMovie(false);
      }
    } else {
      // Standard upload to backend (local dev fallback)
      const formData = new FormData();
      formData.append("file", selectedFile);
      formData.append("title", titleToUse);
      formData.append("host_id", user.id);

      try {
        const xhr = new XMLHttpRequest();
        xhr.open("POST", `${backendUrl}/api/rooms/${code}/upload`, true);

        xhr.upload.onprogress = (event) => {
          if (event.lengthComputable) {
            const percent = Math.round((event.loaded / event.total) * 100);
            setUploadProgress(percent);
          }
        };

        xhr.onload = () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            console.log("Upload completed successfully!");
            setSelectedFile(null);
            setCustomTitle("");
            setRoomState("streaming");
          } else {
            try {
              const errResponse = JSON.parse(xhr.responseText);
              setUploadError(errResponse.detail || "Failed to upload movie.");
            } catch {
              setUploadError("Failed to upload movie.");
            }
          }
          setUploadingMovie(false);
        };

        xhr.onerror = () => {
          setUploadError("Network error occurred during upload.");
          setUploadingMovie(false);
        };

        xhr.send(formData);
      } catch (err: any) {
        setUploadError(err.message || "Failed to initiate upload.");
        setUploadingMovie(false);
      }
    }
  };

  const renderUploadForm = () => {
    return (
      <form onSubmit={handleUploadMovie} className="space-y-4">
        {/* Movie Title */}
        <div className="space-y-1.5">
          <label htmlFor="movieTitle" className="text-xs font-semibold text-zinc-300">
            Movie / Stream Title
          </label>
          <input
            id="movieTitle"
            type="text"
            value={customTitle}
            onChange={(e) => setCustomTitle(e.target.value)}
            placeholder={matches?.matches[0]?.title || "e.g. Inception"}
            className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-indigo-500/50 text-white rounded-xl px-4 py-3 text-sm outline-none transition-all"
          />
        </div>

        {/* File Selector */}
        <div className="space-y-1.5">
          <label className="text-xs font-semibold text-zinc-300 block">
            Select MP4 File
          </label>
          <div className="relative group border border-dashed border-zinc-800 hover:border-indigo-500/50 rounded-2xl p-6 text-center cursor-pointer transition-all bg-zinc-950/40">
            <input
              type="file"
              accept="video/mp4"
              onChange={(e) => {
                if (e.target.files && e.target.files[0]) {
                  setSelectedFile(e.target.files[0]);
                }
              }}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div className="flex flex-col items-center justify-center gap-2">
              <Film className="w-8 h-8 text-zinc-500 group-hover:text-indigo-400 transition-colors" />
              {selectedFile ? (
                <div>
                  <p className="text-sm font-semibold text-indigo-400">{selectedFile.name}</p>
                  <p className="text-[10px] text-zinc-500 font-medium">
                    {(selectedFile.size / (1024 * 1024)).toFixed(1)} MB
                  </p>
                </div>
              ) : (
                <div>
                  <p className="text-xs text-zinc-400 font-medium">
                    Click or drag & drop an MP4 video file
                  </p>
                  <p className="text-[10px] text-zinc-600 mt-0.5">
                    MP4 up to 500MB recommended
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>

        {uploadError && (
          <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/20 px-3 py-2 rounded-lg">
            ⚠️ {uploadError}
          </p>
        )}

        {/* Submit Button / Progress */}
        {uploadingMovie ? (
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-semibold">
              <span className="text-indigo-400 animate-pulse">Uploading file to server...</span>
              <span className="text-zinc-400">{uploadProgress}%</span>
            </div>
            <div className="w-full bg-zinc-900 rounded-full h-2 overflow-hidden border border-zinc-800">
              <div
                className="h-full bg-gradient-to-r from-indigo-500 to-purple-600 rounded-full transition-all duration-300"
                style={{ width: `${uploadProgress}%` }}
              />
            </div>
            <p className="text-[10px] text-zinc-500 italic text-center animate-pulse">
              Once uploaded, transcoding starts automatically and the stream begins.
            </p>
          </div>
        ) : (
          <button
            type="submit"
            disabled={!selectedFile}
            className={`w-full bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white rounded-2xl py-3.5 font-bold text-sm shadow-[0_4px_25px_rgba(99,102,241,0.2)] transition-all flex items-center justify-center gap-2 ${
              !selectedFile ? "opacity-50 cursor-not-allowed" : "cursor-pointer active:scale-[0.98]"
            }`}
          >
            <Play className="w-4 h-4 fill-white" />
            Upload & Start Co-Watching
          </button>
        )}
      </form>
    );
  };

  const allVibesSelected =
    members.length > 0 &&
    members.every((m) => m.genres && m.genres.length > 0);

  const meInMembers = members.find((m) => m.id === user?.id);
  const showVibeNotification =
    meInMembers?.notified && selectedGenres.length === 0;

  /* ── Loading ──────────────────────────────────────────────────────────── */
  if (loadingUser) {
    return (
      <div className="flex-1 min-h-screen flex flex-col items-center justify-center bg-[#050508]">
        <VideoLoader text="Loading session..." />
      </div>
    );
  }

  /* ── Direct join gate ─────────────────────────────────────────────────── */
  if (!user) {
    return (
      <div className="flex-1 min-h-screen flex flex-col items-center justify-center p-4">
        <div className="glass glass-glow rounded-3xl p-8 w-full max-w-md space-y-6">
          <div className="text-center">
            <h1 className="text-3xl font-black text-white mb-1">Join Session</h1>
            <p className="text-xs text-zinc-400">
              Room Code:{" "}
              <span className="text-indigo-400 font-bold tracking-widest">
                {code}
              </span>
            </p>
          </div>
          <form onSubmit={joinDirect} className="space-y-4">
            <div className="space-y-1.5">
              <label
                htmlFor="directName"
                className="text-xs font-semibold text-zinc-300"
              >
                Your Name
              </label>
              <input
                id="directName"
                type="text"
                value={directName}
                onChange={(e) => setDirectName(e.target.value)}
                placeholder="e.g. Atul"
                className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-indigo-500/50 text-white rounded-xl px-4 py-3 text-sm outline-none"
              />
            </div>
            {directError && (
              <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/20 px-3 py-2 rounded-lg">
                {directError}
              </p>
            )}
            <button
              type="submit"
              disabled={joiningDirect}
              className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-xl py-3 font-semibold text-sm transition-all active:scale-[0.98] cursor-pointer disabled:opacity-50"
            >
              {joiningDirect ? "Joining…" : "Join Room"}
            </button>
          </form>
        </div>
      </div>
    );
  }

  /* ── Main room layout ─────────────────────────────────────────────────── */
  return (
    <div className="flex-1 flex flex-col p-4 md:p-6 min-h-screen max-w-5xl mx-auto w-full">
      {/* Header */}
      <header className="flex justify-between items-center py-4 border-b border-zinc-800/80 mb-6">
        <button
          onClick={() => router.push("/")}
          className="flex items-center gap-2.5 cursor-pointer group"
        >
          <img
            src="/loaders/logo.png"
            alt="MovieMatch Logo"
            className="w-12 h-auto object-contain transition-all duration-300 group-hover:scale-105"
            style={{
              filter: "drop-shadow(0 0 6px rgba(99, 102, 241, 0.6))"
            }}
          />
          <span className="font-black text-lg text-white group-hover:text-indigo-400 transition-colors">MovieMatch</span>
        </button>
        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <p className="text-xs font-bold text-white">{user.name}</p>
            <p className="text-[10px] text-zinc-500 capitalize">
              {user.role} · {groupType}
            </p>
          </div>
          <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-600 flex items-center justify-center font-bold text-white text-xs">
            {user.name[0].toUpperCase()}
          </div>
        </div>
      </header>

      {/* Error banner */}
      {errorMsg && (
        <div className="bg-rose-500/10 border border-rose-500/25 text-rose-400 text-xs px-4 py-3 rounded-xl flex items-center gap-2 mb-6">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}

      {/* Vibe selection reminder notification */}
      {showVibeNotification && (
        <div className="bg-indigo-500/10 border border-indigo-500/25 text-indigo-300 text-xs px-4 py-3 rounded-xl flex items-center gap-2 mb-6 animate-pulse">
          <Sparkles className="w-4 h-4 text-indigo-400 shrink-0" />
          <span>🔔 Host is waiting for you to select your movie vibe below!</span>
        </div>
      )}

      {/* ── WAITING ────────────────────────────────────────────────────── */}
      {roomState === "waiting" && (
        <div className="flex-1 grid md:grid-cols-5 gap-8 items-start">
          {/* Left: room info */}
          <div className="md:col-span-3 space-y-5">
            {groupType === "stream" ? (
              user.role === "host" ? (
                /* Co-Watch Streaming Upload Card (Direct Stream version) */
                <div className="glass glass-glow rounded-3xl p-6 md:p-8 border border-zinc-800/80 space-y-6">
                  <div>
                    <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest block mb-1 animate-pulse">
                      Direct Stream Room
                    </span>
                    <h2 className="text-2xl font-black text-white flex items-center gap-2">
                      🍿 Start Watch Party
                    </h2>
                    <p className="text-zinc-400 text-xs mt-1">
                      Upload an MP4 file to stream with everyone in the room! Playback is synced in real-time and cameras can be shared.
                    </p>
                  </div>
                  {renderUploadForm()}
                </div>
              ) : (
                /* Guest view waiting for host upload */
