            <button
              type="submit"
              disabled={joiningDirect}
              className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-xl py-3 font-semibold text-sm transition-all active:scale-[0.98] cursor-pointer disabled:opacity-50"
            >
              {joiningDirect ? "Joining…" : "Join Room"}
            </button>
          </form>
        </div>
      </div>
    );
  }

  /* ── Main room layout ─────────────────────────────────────────────────── */
  return (
    <div className="flex-1 flex flex-col p-4 md:p-6 min-h-screen max-w-5xl mx-auto w-full">
      {/* Header */}
      <header className="flex justify-between items-center py-4 border-b border-zinc-800/80 mb-6">
        <button
          onClick={() => router.push("/")}
          className="flex items-center gap-2.5 cursor-pointer group"
        >
          <img
            src="/loaders/logo.png"
            alt="MovieMatch Logo"
            className="w-12 h-auto object-contain transition-all duration-300 group-hover:scale-105"
            style={{
              filter: "drop-shadow(0 0 6px rgba(99, 102, 241, 0.6))"
            }}
          />
          <span className="font-black text-lg text-white group-hover:text-indigo-400 transition-colors">MovieMatch</span>
        </button>
        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <p className="text-xs font-bold text-white">{user.name}</p>
            <p className="text-[10px] text-zinc-500 capitalize">
              {user.role} · {groupType}
            </p>
          </div>
          <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-600 flex items-center justify-center font-bold text-white text-xs">
            {user.name[0].toUpperCase()}
          </div>
        </div>
      </header>

      {/* Error banner */}
      {errorMsg && (
        <div className="bg-rose-500/10 border border-rose-500/25 text-rose-400 text-xs px-4 py-3 rounded-xl flex items-center gap-2 mb-6">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}

      {/* Vibe selection reminder notification */}
      {showVibeNotification && (
        <div className="bg-indigo-500/10 border border-indigo-500/25 text-indigo-300 text-xs px-4 py-3 rounded-xl flex items-center gap-2 mb-6 animate-pulse">
          <Sparkles className="w-4 h-4 text-indigo-400 shrink-0" />
          <span>🔔 Host is waiting for you to select your movie vibe below!</span>
        </div>
