                      <span className="text-[10px] text-zinc-500 uppercase tracking-wider font-bold block">
                        Room Code
                      </span>
                      <span className="text-xl font-black tracking-widest text-white">
                        {code}
                      </span>
                    </div>
                    <div className="flex gap-2">
                      <button
