// @kestrel Defense-in-Depth Allowlist & Parameterized Guard (React / TypeScript)
"use client";

import { useEffect, useRef, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import {
  AlertCircle,
  ArrowLeft,
  Check,
  Copy,
  Film,
  Play,
  RefreshCw,
  Sparkles,
  Star,
  Users,
} from "lucide-react";
import Confetti from "@/components/Confetti";
import SwipeDeck from "@/components/SwipeDeck";
import VideoLoader from "@/components/VideoLoader";
import WatchRoomView from "@/components/WatchRoomView";

/* ── Types ────────────────────────────────────────────────────────────────── */

interface RoomUser {
  id: string;
  name: string;
  role: "host" | "guest";
}

interface Member {
  id: string;
  name: string;
  genres?: string[];
  notified?: boolean;
}

interface MovieCard {
  tmdb_id: string;
  position: number;
  title: string;
  overview: string | null;
  poster_path: string | null;
  genres: string | null;
  rating: number | null;
  runtime: number | null;
  streaming_info: string | null;
}

interface MatchMovie {
  tmdb_id: string;
  title: string;
  overview: string | null;
  poster_path: string | null;
  genres: string | null;
  rating: number | null;
  runtime: number | null;
  streaming_info: string | null;
  yes_count: number;
  is_unanimous: boolean;
}

interface MatchResult {
  total_members: number;
  matches: MatchMovie[];
}

type RoomState = "waiting" | "swiping" | "revealed" | "streaming";

type ProgressMap = Record<
  string,
  { name: string; voted: number; total: number }
>;

const AVAILABLE_GENRES = [
  "Action",
  "Comedy",
  "Romance",
  "Drama",
  "Sci-Fi",
  "Horror",
  "Thriller",
  "Documentary",
  "Animation",
];

/* ── Component ────────────────────────────────────────────────────────────── */

export default function RoomPage() {
  const params = useParams();
  const router = useRouter();
  const code = (params.code as string).toUpperCase();
  const backendUrl =
    process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:8000";

  /* user identity */
  const [user, setUser] = useState<RoomUser | null>(null);
  const [loadingUser, setLoadingUser] = useState(true);

  /* direct-join form (when arriving via invite link) */
  const [directName, setDirectName] = useState("");
  const [directError, setDirectError] = useState("");
  const [joiningDirect, setJoiningDirect] = useState(false);

  /* room state */
  const [roomState, setRoomState] = useState<RoomState>("waiting");
  const [groupType, setGroupType] = useState("");
  const [members, setMembers] = useState<Member[]>([]);
  const [movies, setMovies] = useState<MovieCard[]>([]);
  const [progress, setProgress] = useState<ProgressMap>({});
  const [matches, setMatches] = useState<MatchResult | null>(null);
  const [selectedGenres, setSelectedGenres] = useState<string[]>([]);

  /* ui */
  const [copiedCode, setCopiedCode] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  /* movie streaming upload state */
  const [uploadingMovie, setUploadingMovie] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [customTitle, setCustomTitle] = useState("");
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [uploadError, setUploadError] = useState("");

  const moviesLoadedRef = useRef(false);
  const matchesLoadedRef = useRef(false);
  const genresInitializedRef = useRef(false);
  const socketRef = useRef<WebSocket | null>(null);

  /* ── 2. Load user from localStorage ──────────────────────────────────── */
  useEffect(() => {
    const saved = localStorage.getItem(`room_${code}_user`);
    if (saved) {
      try {
        setUser(JSON.parse(saved));
      } catch {
        /* ignore corrupt data */
      }
    }
    setLoadingUser(false);
  }, [code]);

  /* ── 3. Fetch room details ────────────────────────────────────────────── */
  const fetchRoom = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}`);
      if (!res.ok) throw new Error("Room not found");
      const data = await res.json();
      setGroupType(data.group_type);
      setRoomState(data.state as RoomState);
      setMembers(data.members);
      setErrorMsg(""); // Clear errors on success

      // Initialize progress mapping from database values
      if (data.state === "swiping" || data.state === "revealed") {
        const initProgress: ProgressMap = {};
        data.members.forEach((m: any) => {
          if (m.voted_count !== undefined && m.voted_count !== null) {
            initProgress[m.id] = {
              name: m.name,
              voted: m.voted_count,
              total: 20,
            };
          }
        });
        setProgress(initProgress);
      }

      // Initialize selected genres for this user from room details response (ONLY ONCE)
      if (user && !genresInitializedRef.current) {
        const me = data.members.find((m: any) => m.id === user.id);
        if (me && me.genres) {
          setSelectedGenres(me.genres);
          genresInitializedRef.current = true;
        }
      }

      if (data.state === "swiping" && !moviesLoadedRef.current) {
        fetchDeck();
      }
      if (data.state === "revealed" && !matchesLoadedRef.current) {
        fetchMatches();
      }
    } catch (err: unknown) {
      setErrorMsg(err instanceof Error ? err.message : "Failed to load room");
    }
  };

  const fetchDeck = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/recs`);
      if (res.ok) {
        setMovies(await res.json());
        moviesLoadedRef.current = true;
      }
    } catch (err) {
      console.error("Failed to fetch deck:", err);
    }
  };

  const fetchMatches = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/matches`);
      if (res.ok) {
        setMatches(await res.json());
        matchesLoadedRef.current = true;
      }
    } catch (err) {
      console.error("Failed to fetch matches:", err);
    }
  };

  /* ── 4. Short Polling & WebSocket Real-time Sync ──────────────────────── */
  useEffect(() => {
    if (loadingUser || !user) return;

    // Initial fetch
    fetchRoom();

    // Poll every 2 seconds (as backup/sync fallback)
    const interval = setInterval(() => {
      fetchRoom();
    }, 2000);

    // Connect to WebSocket
    let reconnectTimeout: NodeJS.Timeout;
    let reconnectDelay = 3000;

    const connect = () => {
      const wsProto = window.location.protocol === "https:" ? "wss:" : "ws:";

      // Resolve host dynamically to avoid Windows localhost IPv6 ([::1]) vs IPv4 (127.0.0.1) resolution issues
      let backendHost = backendUrl.replace(/^https?:\/\//, "");
      if (backendHost.startsWith("localhost:")) {
        const port = backendHost.split(":")[1] || "8000";
        if (window.location.hostname !== "localhost" && window.location.hostname !== "") {
          backendHost = `${window.location.hostname}:${port}`;
        } else {
          backendHost = `127.0.0.1:${port}`;
        }
      }

      const wsUrl = `${wsProto}//${backendHost}/ws/${code}/${user.id}`;

      console.log("Connecting to WebSocket:", wsUrl);
      const ws = new WebSocket(wsUrl);
      socketRef.current = ws;

      ws.onopen = () => {
        console.log("WebSocket connection established");
        reconnectDelay = 3000; // Reset delay on success
      };

      ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.event === "state_changed") {
            setRoomState(data.state as RoomState);
            if (data.state === "swiping" && !moviesLoadedRef.current) {
              fetchDeck();
            }
            if (data.state === "revealed") {
              if (data.matches) {
                setMatches(data.matches);
                matchesLoadedRef.current = true;
              } else {
                fetchMatches();
              }
            }
          } else if (data.event === "participant_joined" || data.event === "participant_left") {
            if (data.participants) {
              const newMembers = data.participants.map((p: any) => ({
                id: p.id,
                name: p.name,
                genres: p.genres,
                notified: p.notified
              }));
              setMembers(newMembers);
            }
          } else if (data.event === "vote_progress") {
            setProgress((prev) => ({
              ...prev,
              [data.user_id]: {
                name: data.user_name,
                voted: data.voted_count,
                total: data.total_count,
              },
            }));
          }
        } catch (err) {
          console.error("Error processing WebSocket message:", err);
        }
      };

      ws.onclose = (event) => {
        console.log(`WebSocket connection closed (code: ${event.code}). Reconnecting in ${reconnectDelay / 1000}s...`);
        reconnectTimeout = setTimeout(() => {
          connect();
        }, reconnectDelay);
        reconnectDelay = Math.min(reconnectDelay * 1.5, 30000); // Exponential backoff up to 30s
      };

      ws.onerror = (err) => {
        console.error("WebSocket error:", err);
      };
    };

    connect();

    return () => {
      clearInterval(interval);
      if (socketRef.current) {
        socketRef.current.onclose = null;
        socketRef.current.close();
      }
      clearTimeout(reconnectTimeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadingUser, user]);

  /* ── 4. Actions ───────────────────────────────────────────────────────── */
  const startSession = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/start`, {
        method: "POST",
      });
      if (!res.ok) {
        throw new Error((await res.json()).detail || "Could not start session");
      }
    } catch (err: unknown) {
      setErrorMsg(err instanceof Error ? err.message : "Network error - failed to start session");
    }
  };

  const castVote = async (tmdbId: string, choice: boolean) => {
    if (!user) return;
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/vote`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, tmdb_id: tmdbId, choice }),
      });
      if (!res.ok) {
        throw new Error((await res.json()).detail || "Failed to record vote");
      }
    } catch (err: unknown) {
      console.error("Failed to cast vote:", err);
      setErrorMsg(err instanceof Error ? err.message : "Network error - failed to save vote");
    }
  };

  const forceReveal = async () => {
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/reveal`, {
        method: "POST",
      });
      if (!res.ok) {
        throw new Error((await res.json()).detail || "Could not reveal matches");
      }
      const data = await res.json();
      setMatches(data);
      setRoomState("revealed");
    } catch (err: unknown) {
      setErrorMsg(err instanceof Error ? err.message : "Failed to force reveal matches");
    }
  };

  const toggleGenre = async (genre: string) => {
    if (!user) return;
    const updated = selectedGenres.includes(genre)
      ? selectedGenres.filter((g) => g !== genre)
      : [...selectedGenres, genre];

    setSelectedGenres(updated);

    try {
      const res = await fetch(`${backendUrl}/api/users/${user.id}/genres`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ genres: updated }),
      });
      if (!res.ok) {
        console.error("Failed to save genres to backend");
      }
    } catch (err) {
      console.error("Failed to save genres:", err);
    }
  };

  const joinDirect = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!directName.trim()) return setDirectError("Name is required");
    setDirectError("");
    setJoiningDirect(true);
    try {
      const res = await fetch(`${backendUrl}/api/rooms/${code}/join`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: directName.trim() }),
      });
      if (!res.ok)
        throw new Error((await res.json()).detail || "Could not join room");
      const data = await res.json();
      const newUser: RoomUser = {
        id: data.user_id,
        name: data.user_name,
        role: "guest",
      };
      localStorage.setItem(`room_${code}_user`, JSON.stringify(newUser));
      setUser(newUser);
    } catch (err: unknown) {
      setDirectError(err instanceof Error ? err.message : "Failed to join");
      setJoiningDirect(false);
    }
  };

  const copyCode = () => {
    navigator.clipboard.writeText(code);
    setCopiedCode(true);
    setTimeout(() => setCopiedCode(false), 2500);
  };

  const copyLink = () => {
    navigator.clipboard.writeText(`${window.location.origin}/room/${code}`);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2500);
  };

  const notifyPlayer = async (userId: string) => {
    try {
      const res = await fetch(`${backendUrl}/api/users/${userId}/notify`, {
        method: "POST",
      });
      if (!res.ok) {
        console.error("Failed to notify player");
      } else {
        fetchRoom();
      }
    } catch (err) {
      console.error("Failed to notify player:", err);
    }
  };

  const handleUploadMovie = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFile || !user) return;

    const titleToUse = customTitle.trim() || (matches?.matches[0]?.title) || "Group Watch Party";

    setUploadingMovie(true);
    setUploadProgress(0);
    setUploadError("");

    let supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

    if (supabaseUrl && anonKey) {
      // Normalize URL (strip trailing slashes and /rest/v1 path suffix)
      supabaseUrl = supabaseUrl.replace(/\/+$/, "").replace(/\/rest\/v1$/, "");

      // Direct upload to Supabase Storage (Bypasses Vercel payload limit)
      const filename = `${code}_${Date.now()}_${selectedFile.name.replace(/[^a-zA-Z0-9.]/g, "_")}`;
      const uploadUrl = `${supabaseUrl}/storage/v1/object/MovieMatch/${filename}`;

      try {
        const xhr = new XMLHttpRequest();
        xhr.open("POST", uploadUrl, true);
        xhr.setRequestHeader("Authorization", `Bearer ${anonKey}`);
        xhr.setRequestHeader("apikey", anonKey);

        xhr.upload.onprogress = (event) => {
          if (event.lengthComputable) {
            const percent = Math.round((event.loaded / event.total) * 100);
            setUploadProgress(percent);
          }
        };

        xhr.onload = async () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            const publicUrl = `${supabaseUrl}/storage/v1/object/public/MovieMatch/${filename}`;

            try {
              const res = await fetch(`${backendUrl}/api/rooms/${code}/stream_url`, {
                method: "POST",
                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                body: new URLSearchParams({
                  title: titleToUse,
                  host_id: user.id,
                  stream_url: publicUrl
                })
              });
              if (res.ok) {
                console.log("Direct upload & registration completed successfully!");
                setSelectedFile(null);
                setCustomTitle("");
                setRoomState("streaming");
              } else {
                setUploadError("Failed to register stream URL on backend.");
              }
            } catch (err: any) {
              setUploadError("Network error registering stream URL on backend.");
            }
          } else {
            setUploadError("Failed to upload video to Supabase Storage.");
          }
          setUploadingMovie(false);
        };

        xhr.onerror = () => {
          setUploadError("Network error occurred during direct upload.");
          setUploadingMovie(false);
        };

        xhr.send(selectedFile);
      } catch (err: any) {
        setUploadError(err.message || "Failed to initiate direct upload.");
        setUploadingMovie(false);
      }
    } else {
      // Standard upload to backend (local dev fallback)
      const formData = new FormData();
      formData.append("file", selectedFile);
      formData.append("title", titleToUse);
      formData.append("host_id", user.id);

      try {
        const xhr = new XMLHttpRequest();
        xhr.open("POST", `${backendUrl}/api/rooms/${code}/upload`, true);

        xhr.upload.onprogress = (event) => {
          if (event.lengthComputable) {
            const percent = Math.round((event.loaded / event.total) * 100);
            setUploadProgress(percent);
          }
        };

        xhr.onload = () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            console.log("Upload completed successfully!");
            setSelectedFile(null);
            setCustomTitle("");
            setRoomState("streaming");
          } else {
            try {
              const errResponse = JSON.parse(xhr.responseText);
              setUploadError(errResponse.detail || "Failed to upload movie.");
            } catch {
              setUploadError("Failed to upload movie.");
            }
          }
          setUploadingMovie(false);
        };

        xhr.onerror = () => {
          setUploadError("Network error occurred during upload.");
          setUploadingMovie(false);
        };

        xhr.send(formData);
      } catch (err: any) {
        setUploadError(err.message || "Failed to initiate upload.");
        setUploadingMovie(false);
      }
    }
  };

  const renderUploadForm = () => {
    return (
      <form onSubmit={handleUploadMovie} className="space-y-4">
        {/* Movie Title */}
        <div className="space-y-1.5">
          <label htmlFor="movieTitle" className="text-xs font-semibold text-zinc-300">
            Movie / Stream Title
          </label>
          <input
            id="movieTitle"
            type="text"
            value={customTitle}
            onChange={(e) => setCustomTitle(e.target.value)}
            placeholder={matches?.matches[0]?.title || "e.g. Inception"}
            className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-indigo-500/50 text-white rounded-xl px-4 py-3 text-sm outline-none transition-all"
          />
        </div>

        {/* File Selector */}
        <div className="space-y-1.5">
          <label className="text-xs font-semibold text-zinc-300 block">
            Select MP4 File
          </label>
          <div className="relative group border border-dashed border-zinc-800 hover:border-indigo-500/50 rounded-2xl p-6 text-center cursor-pointer transition-all bg-zinc-950/40">
            <input
              type="file"
              accept="video/mp4"
              onChange={(e) => {
                if (e.target.files && e.target.files[0]) {
                  setSelectedFile(e.target.files[0]);
                }
              }}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div className="flex flex-col items-center justify-center gap-2">
              <Film className="w-8 h-8 text-zinc-500 group-hover:text-indigo-400 transition-colors" />
              {selectedFile ? (
                <div>
                  <p className="text-sm font-semibold text-indigo-400">{selectedFile.name}</p>
                  <p className="text-[10px] text-zinc-500 font-medium">
                    {(selectedFile.size / (1024 * 1024)).toFixed(1)} MB
                  </p>
                </div>
              ) : (
                <div>
                  <p className="text-xs text-zinc-400 font-medium">
                    Click or drag & drop an MP4 video file
                  </p>
                  <p className="text-[10px] text-zinc-600 mt-0.5">
                    MP4 up to 500MB recommended
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>

        {uploadError && (
          <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/20 px-3 py-2 rounded-lg">
            ⚠️ {uploadError}
          </p>
        )}

        {/* Submit Button / Progress */}
        {uploadingMovie ? (
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-semibold">
              <span className="text-indigo-400 animate-pulse">Uploading file to server...</span>
              <span className="text-zinc-400">{uploadProgress}%</span>
            </div>
            <div className="w-full bg-zinc-900 rounded-full h-2 overflow-hidden border border-zinc-800">
              <div
                className="h-full bg-gradient-to-r from-indigo-500 to-purple-600 rounded-full transition-all duration-300"
                style={{ width: `${uploadProgress}%` }}
              />
            </div>
            <p className="text-[10px] text-zinc-500 italic text-center animate-pulse">
              Once uploaded, transcoding starts automatically and the stream begins.
            </p>
          </div>
        ) : (
          <button
            type="submit"
            disabled={!selectedFile}
            className={`w-full bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white rounded-2xl py-3.5 font-bold text-sm shadow-[0_4px_25px_rgba(99,102,241,0.2)] transition-all flex items-center justify-center gap-2 ${
              !selectedFile ? "opacity-50 cursor-not-allowed" : "cursor-pointer active:scale-[0.98]"
            }`}
          >
            <Play className="w-4 h-4 fill-white" />
            Upload & Start Co-Watching
          </button>
        )}
      </form>
    );
  };

  const allVibesSelected =
    members.length > 0 &&
    members.every((m) => m.genres && m.genres.length > 0);

  const meInMembers = members.find((m) => m.id === user?.id);
  const showVibeNotification =
    meInMembers?.notified && selectedGenres.length === 0;

  /* ── Loading ──────────────────────────────────────────────────────────── */
  if (loadingUser) {
    return (
      <div className="flex-1 min-h-screen flex flex-col items-center justify-center bg-[#050508]">
        <VideoLoader text="Loading session..." />
      </div>
    );
  }

  /* ── Direct join gate ─────────────────────────────────────────────────── */
  if (!user) {
    return (
      <div className="flex-1 min-h-screen flex flex-col items-center justify-center p-4">
        <div className="glass glass-glow rounded-3xl p-8 w-full max-w-md space-y-6">
          <div className="text-center">
            <h1 className="text-3xl font-black text-white mb-1">Join Session</h1>
            <p className="text-xs text-zinc-400">
              Room Code:{" "}
              <span className="text-indigo-400 font-bold tracking-widest">
                {code}
              </span>
            </p>
          </div>
          <form onSubmit={joinDirect} className="space-y-4">
            <div className="space-y-1.5">
              <label
                htmlFor="directName"
                className="text-xs font-semibold text-zinc-300"
              >
                Your Name
              </label>
              <input
                id="directName"
                type="text"
                value={directName}
                onChange={(e) => setDirectName(e.target.value)}
                placeholder="e.g. Atul"
                className="w-full bg-zinc-900/60 border border-zinc-800 focus:border-indigo-500/50 text-white rounded-xl px-4 py-3 text-sm outline-none"
              />
            </div>
            {directError && (
              <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/20 px-3 py-2 rounded-lg">
                {directError}
              </p>
            )}
            <button
              type="submit"
              disabled={joiningDirect}
              className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-xl py-3 font-semibold text-sm transition-all active:scale-[0.98] cursor-pointer disabled:opacity-50"
            >
              {joiningDirect ? "Joining…" : "Join Room"}
            </button>
          </form>
        </div>
      </div>
    );
  }

  /* ── Main room layout ─────────────────────────────────────────────────── */
  return (
    <div className="flex-1 flex flex-col p-4 md:p-6 min-h-screen max-w-5xl mx-auto w-full">
      {/* Header */}
      <header className="flex justify-between items-center py-4 border-b border-zinc-800/80 mb-6">
        <button
          onClick={() => router.push("/")}
          className="flex items-center gap-2.5 cursor-pointer group"
        >
          <img
            src="/loaders/logo.png"
            alt="MovieMatch Logo"
            className="w-12 h-auto object-contain transition-all duration-300 group-hover:scale-105"
            style={{
              filter: "drop-shadow(0 0 6px rgba(99, 102, 241, 0.6))"
            }}
          />
          <span className="font-black text-lg text-white group-hover:text-indigo-400 transition-colors">MovieMatch</span>
        </button>
        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <p className="text-xs font-bold text-white">{user.name}</p>
            <p className="text-[10px] text-zinc-500 capitalize">
              {user.role} · {groupType}
            </p>
          </div>
          <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-600 flex items-center justify-center font-bold text-white text-xs">
            {user.name[0].toUpperCase()}
          </div>
        </div>
      </header>

      {/* Error banner */}
      {errorMsg && (
        <div className="bg-rose-500/10 border border-rose-500/25 text-rose-400 text-xs px-4 py-3 rounded-xl flex items-center gap-2 mb-6">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}

      {/* Vibe selection reminder notification */}
      {showVibeNotification && (
        <div className="bg-indigo-500/10 border border-indigo-500/25 text-indigo-300 text-xs px-4 py-3 rounded-xl flex items-center gap-2 mb-6 animate-pulse">
          <Sparkles className="w-4 h-4 text-indigo-400 shrink-0" />
          <span>🔔 Host is waiting for you to select your movie vibe below!</span>
        </div>
      )}

      {/* ── WAITING ────────────────────────────────────────────────────── */}
      {roomState === "waiting" && (
        <div className="flex-1 grid md:grid-cols-5 gap-8 items-start">
          {/* Left: room info */}
          <div className="md:col-span-3 space-y-5">
            {groupType === "stream" ? (
              user.role === "host" ? (
                /* Co-Watch Streaming Upload Card (Direct Stream version) */
                <div className="glass glass-glow rounded-3xl p-6 md:p-8 border border-zinc-800/80 space-y-6">
                  <div>
                    <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest block mb-1 animate-pulse">
                      Direct Stream Room
                    </span>
                    <h2 className="text-2xl font-black text-white flex items-center gap-2">
                      🍿 Start Watch Party
                    </h2>
                    <p className="text-zinc-400 text-xs mt-1">
                      Upload an MP4 file to stream with everyone in the room! Playback is synced in real-time and cameras can be shared.
                    </p>
                  </div>
                  {renderUploadForm()}
                </div>
              ) : (
                /* Guest view waiting for host upload */
                <div className="glass rounded-3xl p-8 border border-zinc-800/80 text-center space-y-6 min-h-[300px] flex flex-col items-center justify-center">
                  <div className="w-10 h-10 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin" />
                  <div>
                    <h2 className="text-xl font-bold text-white">Stream is being set up</h2>
                    <p className="text-zinc-400 text-xs mt-1">
                      Waiting for the host to upload a movie. You will enter the Watch Room automatically once the stream starts!
                    </p>
                  </div>

                  {/* Share code block for guest convenience */}
                  <div className="bg-zinc-950 rounded-2xl border border-zinc-900 p-4 flex items-center justify-between w-full max-w-sm">
                    <div>
                      <span className="text-[10px] text-zinc-500 uppercase tracking-wider font-bold block">
                        Room Code
                      </span>
                      <span className="text-xl font-black tracking-widest text-white">
                        {code}
                      </span>
                    </div>
                    <div className="flex gap-2">
                      <button
                        onClick={copyCode}
                        className="bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-400 border border-indigo-500/20 px-2.5 py-1.5 rounded-xl text-[10px] font-bold transition-all cursor-pointer"
                      >
                        {copiedCode ? "Copied!" : "Copy Code"}
                      </button>
                    </div>
                  </div>
                </div>
              )
            ) : (
              <div className="glass rounded-3xl p-6 md:p-8 space-y-6">
                <div>
                  <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest block mb-1">
                    Lobby
                  </span>
                  <h1 className="text-3xl font-black text-white">
                    Room is ready!
                  </h1>
                  <p className="text-zinc-400 text-sm mt-1">
                    Share the code or invite link. Once everyone's in, the host
                    starts swiping.
                  </p>
                </div>

                {/* Room code */}
                <div className="bg-zinc-950 rounded-2xl border border-zinc-900 p-4 flex items-center justify-between">
                  <div>
                    <span className="text-[10px] text-zinc-500 uppercase tracking-wider font-bold block">
                      Room Code
                    </span>
                    <span className="text-3xl font-black tracking-widest text-white">
                      {code}
                    </span>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={copyCode}
                      className="flex items-center gap-1.5 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-400 border border-indigo-500/20 px-3 py-2 rounded-xl text-xs font-semibold transition-all cursor-pointer"
                    >
                      {copiedCode ? (
                        <>
                          <Check className="w-3.5 h-3.5" /> Copied!
                        </>
                      ) : (
                        <>
                          <Copy className="w-3.5 h-3.5" /> Copy Code
                        </>
                      )}
                    </button>
                    <button
                      onClick={copyLink}
                      className="flex items-center gap-1.5 bg-purple-500/10 hover:bg-purple-500/20 text-purple-400 border border-purple-500/20 px-3 py-2 rounded-xl text-xs font-semibold transition-all cursor-pointer"
                    >
                      {copiedLink ? (
                        <>
                          <Check className="w-3.5 h-3.5" /> Copied!
                        </>
                      ) : (
                        <>
                          <Copy className="w-3.5 h-3.5" /> Copy Link
                        </>
                      )}
                    </button>
                  </div>
                </div>

                {/* Start button (host only) */}
                {user.role === "host" ? (
                  <div className="w-full space-y-2">
                    <button
                      onClick={startSession}
                      disabled={!allVibesSelected}
                      className={`w-full bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white rounded-2xl py-4 font-bold text-sm shadow-[0_4px_25px_rgba(99,102,241,0.3)] transition-all flex items-center justify-center gap-2 ${
                        !allVibesSelected
                          ? "opacity-50 cursor-not-allowed"
                          : "cursor-pointer"
                      }`}
                    >
                      <Play className="w-4 h-4 fill-white" />
                      Start Swiping
                    </button>
                    {!allVibesSelected && (
                      <p className="text-[10px] text-zinc-500 text-center font-semibold animate-pulse">
                        Waiting for all players to select their movie vibe...
                      </p>
                    )}
                  </div>
                ) : (
                  <div className="w-full bg-zinc-900/30 border border-zinc-800 text-zinc-400 text-xs text-center py-4 rounded-2xl">
                    Waiting for the host to start…
                  </div>
                )}
              </div>
            )}

            {/* Vibe Selection - Only for non-streaming lobbies */}
            {groupType !== "stream" && (
              <div className="glass rounded-3xl p-6 md:p-8 space-y-4">
                <div>
                  <h2 className="text-lg font-bold text-white">Your Movie Vibe</h2>
                  <p className="text-zinc-400 text-xs mt-0.5">
                    Select genres you feel like watching. We will combine everyone's choices to shape the deck!
                  </p>
                </div>
                <div className="flex flex-wrap gap-2 pt-1">
                  {AVAILABLE_GENRES.map((g) => {
                    const selected = selectedGenres.includes(g);
                    return (
                      <button
                        key={g}
                        onClick={() => toggleGenre(g)}
                        className={"px-3.5 py-1.5 rounded-full text-xs font-semibold border transition-all cursor-pointer select-none active:scale-95 $1", /* bound params: [
                          selected
                            ? "bg-indigo-500/20 border-indigo-500 text-indigo-300 shadow-[0_0_12px_rgba(99,102,241,0.15)]"
                            : "bg-zinc-900/60 border-zinc-800 text-zinc-400 hover:border-zinc-700"
                        ] */}
                      >
                        {g}
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
          </div>

          {/* Right: member list */}
          <div className="md:col-span-2 glass rounded-3xl p-6 space-y-4">
            <h2 className="text-xs font-bold text-zinc-300 uppercase tracking-widest flex items-center gap-2">
              <Users className="w-4 h-4" /> Players ({members.length})
            </h2>
            <div className="space-y-2.5">
              {members.map((m) => {
                const isMe = m.id === user.id;
                return (
                  <div
                    key={m.id}
                    className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${
                      isMe
                        ? "border-indigo-500/30 bg-indigo-500/5"
                        : "border-zinc-800 bg-zinc-900/10"
                    }`}
                  >
                    <div className="w-7 h-7 rounded-full bg-zinc-800 flex items-center justify-center font-bold text-xs">
                      {m.name[0].toUpperCase()}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5">
                        <span className="text-sm font-semibold text-zinc-200 truncate">
                          {m.name}
                        </span>
                        {isMe && (
                          <span className="text-indigo-400 text-[10px] font-normal shrink-0">
                            (You)
                          </span>
                        )}
                      </div>
                      <p className="text-[10px] text-zinc-500 truncate mt-0.5">
                        {m.genres && m.genres.length > 0 ? m.genres.join(", ") : "No preferences"}
                      </p>
                    </div>
                    {m.genres && m.genres.length > 0 ? (
                      <div className="flex items-center gap-1 text-[10px] font-bold text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 px-2 py-0.5 rounded-md shrink-0 select-none">
                        <Check className="w-3.5 h-3.5" /> Ready
                      </div>
                    ) : user.role === "host" && !isMe ? (
                      <button
                        onClick={() => notifyPlayer(m.id)}
                        className="flex items-center gap-1 text-[10px] font-bold bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-400 border border-indigo-500/20 px-2 py-1 rounded-md shrink-0 transition-all cursor-pointer active:scale-95 select-none"
                      >
                        🔔 Notify
                      </button>
                    ) : (
                      <div className="text-[10px] font-semibold text-zinc-500 italic shrink-0 select-none">
                        Choosing...
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* ── SWIPING ────────────────────────────────────────────────────── */}
      {roomState === "swiping" &&
        (movies.length > 0 ? (
          <SwipeDeck
            movies={movies}
            onVote={castVote}
            participantName={user.name}
            progressUpdates={progress}
            participants={members}
            isHost={user.role === "host"}
            onForceReveal={forceReveal}
          />
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center">
            <VideoLoader text="Generating your movie deck..." />
          </div>
        ))}

      {/* ── REVEALED ───────────────────────────────────────────────────── */}
      {roomState === "revealed" && matches && (
        <div className="flex-1 flex flex-col space-y-8 pb-10">
          <Confetti />

          {matches.matches.length > 0 ? (
            <div className="space-y-8">
              {/* Title */}
              <div className="text-center space-y-3 max-w-xl mx-auto">
                {matches.matches[0].is_unanimous ? (
                  <div className="inline-flex items-center gap-1.5 bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 px-4 py-1.5 rounded-full text-xs font-extrabold uppercase tracking-wider shadow-[0_0_20px_rgba(16,185,129,0.2)]">
                    <Sparkles className="w-3.5 h-3.5" /> Unanimous Match!
                  </div>
                ) : (
                  <div className="inline-flex items-center gap-1.5 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 px-4 py-1.5 rounded-full text-xs font-extrabold uppercase tracking-wider">
                    <Film className="w-3.5 h-3.5" /> Top Picks
                  </div>
                )}
                <h1 className="text-4xl md:text-5xl font-black text-white">
                  {matches.matches[0].is_unanimous
                    ? "We found a winner! 🎉"
                    : "Close Choices"}
                </h1>
                <p className="text-zinc-400 text-sm">
                  {matches.matches[0].is_unanimous
                    ? "Everyone voted YES. Grab the popcorn!"
                    : "No unanimous hit — here are the most-liked films. Let the group decide!"}
                </p>
              </div>

              {/* Hero movie */}
              {(() => {
                const hero = matches.matches[0];
                return (
                  <div className="glass glass-glow rounded-3xl p-6 md:p-8 max-w-2xl mx-auto grid md:grid-cols-5 gap-6 border border-zinc-800/80">
                    {/* Poster */}
                    <div className="md:col-span-2 aspect-[2/3] bg-zinc-950 rounded-2xl overflow-hidden border border-zinc-800">
                      {hero.poster_path ? (
                        <>
                          <img
                            src={hero.poster_path}
                            alt={hero.title}
                            className="w-full h-full object-cover"
                            onError={(e) => {
                              (e.target as HTMLImageElement).style.display = "none";
                              const fb = document.getElementById("hero-fallback");
                              if (fb) fb.classList.remove("hidden");
                            }}
                          />
                          <div
                            id="hero-fallback"
                            className="hidden absolute inset-0 flex flex-col items-center justify-center text-zinc-500 gap-2 bg-zinc-900"
                          >
                            <Film className="w-10 h-10 text-zinc-700" />
                          </div>
                        </>
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-zinc-700">
                          <Film className="w-10 h-10" />
                        </div>
                      )}
                    </div>
                    {/* Info */}
                    <div className="md:col-span-3 flex flex-col justify-between space-y-4 py-1">
                      <div className="space-y-3">
                        <div className="flex items-center justify-between">
                          <span
                            className={`text-[10px] font-extrabold uppercase tracking-widest px-3 py-1 rounded-full ${
                              hero.is_unanimous
                                ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                                : "bg-zinc-900 text-zinc-400 border border-zinc-800"
                            }`}
                          >
                            {hero.is_unanimous
                              ? "Unanimous"
                              : `${hero.yes_count} / ${matches.total_members} Votes`}
                          </span>
                          {hero.rating && (
                            <span className="flex items-center gap-1 text-xs font-bold text-amber-400">
                              <Star className="w-3.5 h-3.5 fill-amber-400" />
                              {hero.rating}
                            </span>
                          )}
                        </div>
                        <h2 className="text-2xl md:text-3xl font-black text-white leading-tight">
                          {hero.title}
                        </h2>
                        <div className="flex flex-wrap gap-2 text-[10px] font-bold">
                          {hero.runtime && (
                            <span className="bg-zinc-900 border border-zinc-800 text-zinc-300 px-2 py-0.5 rounded-md">
                              {hero.runtime} min
                            </span>
                          )}
                          {hero.genres
                            ?.split(",")
                            .map((g) => (
                              <span
                                key={g}
                                className="bg-zinc-900 border border-zinc-800 text-zinc-300 px-2 py-0.5 rounded-md"
                              >
                                {g.trim()}
                              </span>
                            ))}
                        </div>
                        <p className="text-zinc-400 text-xs md:text-sm leading-relaxed">
                          {hero.overview}
                        </p>
                      </div>
                      {hero.streaming_info && (
                        <div className="space-y-1.5">
                          <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest block">
                            Watch On
                          </span>
                          <div className="flex flex-wrap gap-1.5">
                            {hero.streaming_info.split(",").map((p) => (
                              <span
                                key={p}
                                className="text-[10px] font-semibold bg-indigo-950/20 border border-indigo-900/30 text-indigo-300 px-2.5 py-1 rounded-full"
                              >
                                {p.trim()}
                              </span>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })()}

              {/* Co-Watch Streaming Upload Card */}
              <div className="glass glass-glow rounded-3xl p-6 md:p-8 max-w-2xl mx-auto border border-zinc-800/80 space-y-6">
                <div>
                  <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest block mb-1 animate-pulse">
                    New Feature
                  </span>
                  <h2 className="text-2xl font-black text-white flex items-center gap-2">
                    🍿 Stream & Co-Watch
                  </h2>
                  <p className="text-zinc-400 text-xs mt-1">
                    Upload an MP4 file to stream this movie (or any other video) with the room! Everyone's playback is synced in real-time, and you can share face reactions via camera.
                  </p>
                </div>
                {renderUploadForm()}
              </div>

              {/* Runner-ups */}
              {matches.matches.length > 1 && (
                <div className="max-w-2xl mx-auto space-y-3">
                  <h3 className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
                    Runner-Ups
                  </h3>
                  {matches.matches.slice(1, 4).map((m) => (
                    <div
                      key={m.tmdb_id}
                      className="glass rounded-2xl p-4 flex items-center gap-4 border border-zinc-900"
                    >
                      <div className="w-14 aspect-[2/3] bg-zinc-950 rounded-lg overflow-hidden shrink-0 border border-zinc-800">
                        {m.poster_path ? (
                          <>
                            <img
                              src={m.poster_path}
                              alt={m.title}
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                (e.target as HTMLImageElement).style.display = "none";
                                const fb = document.getElementById(`runner-fallback-${m.tmdb_id}`);
                                if (fb) fb.classList.remove("hidden");
                              }}
                            />
                            <div
                              id={`runner-fallback-${m.tmdb_id}`}
                              className="hidden absolute inset-0 flex items-center justify-center bg-zinc-900 text-zinc-700"
                            >
                              <Film className="w-5 h-5" />
                            </div>
                          </>
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-zinc-700">
                            <Film className="w-5 h-5" />
                          </div>
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between gap-2 mb-1">
                          <h4 className="font-bold text-white text-sm truncate">
                            {m.title}
                          </h4>
                          <span className="text-xs font-bold text-zinc-400 shrink-0">
                            {m.yes_count} yes
                          </span>
                        </div>
                        <p className="text-zinc-500 text-xs line-clamp-1">
                          {m.overview}
                        </p>
                        <div className="flex items-center gap-2 mt-1.5 text-[10px] text-zinc-400">
                          {m.rating && (
                            <>
                              <span className="flex items-center gap-0.5 text-amber-500">
                                <Star className="w-3 h-3 fill-amber-500" />
                                {m.rating}
                              </span>
                              <span>·</span>
                            </>
                          )}
                          {m.runtime && <span>{m.runtime}m</span>}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              <div className="flex justify-center pt-4">
                <button
                  onClick={() => router.push("/")}
                  className="flex items-center gap-2 bg-zinc-900 hover:bg-zinc-800 border border-zinc-800 text-zinc-200 px-6 py-3 rounded-xl text-sm font-semibold transition-all cursor-pointer"
                >
                  <ArrowLeft className="w-4 h-4" /> Back to Home
                </button>
              </div>
            </div>
          ) : (
            /* No matches */
            <div className="max-w-md mx-auto glass rounded-3xl p-10 text-center space-y-5">
              <div className="inline-block p-4 bg-zinc-900 border border-zinc-800 text-zinc-500 rounded-full">
                <AlertCircle className="w-8 h-8" />
              </div>
              <h2 className="text-2xl font-bold text-white">No matches found</h2>
              <p className="text-zinc-400 text-sm">
                Nobody voted YES on any movie. Try a different group type!
              </p>
              <button
                onClick={() => router.push("/")}
                className="bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl px-6 py-3 font-semibold text-sm transition-all cursor-pointer"
              >
                Try Again
              </button>
            </div>
          )}
        </div>
      )}

      {/* ── STREAMING ───────────────────────────────────────────────────── */}
      {roomState === "streaming" && (
        <div className="flex-1 flex flex-col pb-10">
          <WatchRoomView
            roomCode={code}
            userId={user.id}
            userName={user.name}
            isHost={user.role === "host"}
            participants={members}
            ws={socketRef.current}
          />
        </div>
      )}
    </div>
  );
}

